customMethods.script:
system.perspective.print("stateSelected() called with  %s"%(payload))
stateIds = []
stateCategoryPaths = []

for item in payload['selection']:
	if item['value'].has_key('stateId') and item['value']['stateId']: stateIds.append(item['value']['stateId'])
	elif item['value'].has_key('stateCategoryId') and item['value']['stateCategoryId']: stateCategoryPaths.append(item['value']['stateCategoryPath'])
	elif item['value'].get('path') == 'Tool statuses': continue	#The tree's folder for the tool statuses, not a category (868mwzgc8)
	else: stateCategoryPaths.append(item['value']['path'])

self.view.custom.states.selection = {'stateIds': stateIds, 'stateCategoryPaths': stateCategoryPaths}
return


#If there are downtime records associated with the link, then we will disable them
#If there are no records, then we can delete the link

#One toast for the whole selection (868mvvzbz): unlinkAssetState returns (rows, 'Deleted'), (rows, 'Disabled') or (None, reason)
unlinked, disabled, failed = [], [], []
states = self.view.custom.assetStates.selectedData
for row in states:
	retVal, msg = system.kanoa.asset.unlinkAssetState(row['stateAssetLinkId'])
	if msg == 'Disabled': disabled.append(row['stateName'])
	elif msg == 'Deleted': unlinked.append(row['stateName'])
	else: failed.append('%s (%s)' % (row['stateName'], msg))

parts = []
if unlinked: parts.append('unlinked %d state%s' % (len(unlinked), '' if len(unlinked) == 1 else 's'))
if disabled: parts.append('disabled %s instead as %s history' % (', '.join(disabled), 'it has' if len(disabled) == 1 else 'they have'))
if failed: parts.append("couldn't unlink %s" % ', '.join(failed))
if parts:
	message = '; '.join(parts)
	self.toast({'type': 'error' if failed and not (unlinked or disabled) else 'warning' if failed or disabled else 'success', 'message': message[0].upper() + message[1:]})

self.view.refreshBinding("custom.assetStates.data")

return

